const GENERIC = new Set(['united','city','real','sporting','athletic','atletico','club','deportivo','racing','olympique','olympiakos','dynamo','dinamo','inter','nacional','internacional','juventud','union','rovers','wanderers','albion','town'])
const BAD_CRESTS = new Set(['levski sofia'])
export function normTeam(s) {
  return String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/['’`.]/g, '').replace(/[^a-z0-9]+/g, ' ').trim()
}
/** The library slug for a team name, or null when no crest can be named with confidence. */
export function crestSlug(name) {
  const key = normTeam(name)
  if (!key || BAD_CRESTS.has(key)) return null
  if (LOGO_MAP[key]) return LOGO_MAP[key]
  if (LOGO_ALIASES[key] && LOGO_MAP[LOGO_ALIASES[key]]) return LOGO_MAP[LOGO_ALIASES[key]]
  const tokens = key.split(' ').filter(w => w.length >= 3)
  if (!tokens.length) return null
  const counts = Object.create(null)
  for (const tk of tokens) for (const n of LOGO_TOKENS[tk] || []) counts[n] = (counts[n] || 0) + 1
  let best = null, bestScore = 0
  const want = new Set(tokens)
  for (const n in counts) {
    const nt = n.split(' '), ns = new Set(nt)
    if (!(tokens.every(t => ns.has(t)) || nt.every(t => want.has(t)))) continue
    if (counts[n] > bestScore) { bestScore = counts[n]; best = n }
  }
  if (!best) return null
  const bs = new Set(best.split(' ')), matched = tokens.filter(t => bs.has(t))
  if (!matched.some(t => !GENERIC.has(t))) return null
  if (matched.length === 1 && (LOGO_TOKENS[matched[0]] || []).length > 1) return null
  return LOGO_MAP[best]
}
/** The public URL of a team's crest in the library, or null. */
export const crestUrl = name => { const s = crestSlug(name); return s ? `${CREST_BASE}/${s}.png` : null }
